     2	// 서비스 독립성 검사(project 의존 금지), 실행 산출물(bootJar) 이름 고정.
     3	import org.springframework.boot.gradle.plugin.SpringBootPlugin
     4	import org.springframework.boot.gradle.tasks.bundling.BootJar
     5	import org.springframework.boot.gradle.tasks.run.BootRun
     6	
     7	plugins {
     8	  id("org.jetbrains.kotlin.jvm")
     9	  id("org.jetbrains.kotlin.plugin.spring")
    10	  id("org.jetbrains.kotlin.plugin.jpa")
    11	  id("org.springframework.boot")
    12	  id("com.diffplug.spotless")
    13	}
    14	
    15	val catalog = the<VersionCatalogsExtension>().named("libs")
    16	
    17	fun version(name: String): String = catalog.findVersion(name).get().requiredVersion
    18	
    19	java { toolchain { languageVersion = JavaLanguageVersion.of(version("java")) } }
    20	
    21	kotlin {
    22	  compilerOptions {
    23	    freeCompilerArgs.addAll("-Xjsr305=strict", "-Xannotation-default-target=param-property")
    24	  }
    25	}
    26	
    27	// JPA 엔티티는 프록시를 위해 open이어야 한다(엔티티 규칙: docs/common/code-conventions.md).
    28	allOpen {
    29	  annotation("jakarta.persistence.Entity")
    30	  annotation("jakarta.persistence.MappedSuperclass")
    31	  annotation("jakarta.persistence.Embeddable")
    32	}
    33	
    34	dependencies {
    35	  implementation(platform(SpringBootPlugin.BOM_COORDINATES))
    36	  testImplementation(platform(SpringBootPlugin.BOM_COORDINATES))
    37	}
    38	
    39	// POL-ARCH-002: 서비스는 다른 서비스(또는 공유 모듈)에 project(...) 의존을 만들지 않는다.
    40	configurations.configureEach {
    41	  val configurationName = name
    42	  dependencies.withType<ProjectDependency>().configureEach {
    43	    throw GradleException(
    44	      "서비스 독립성 위반(POL-ARCH-002): ${project.path}의 $configurationName 에 project 의존 '$path'가 있습니다. " +
    45	        "다른 서비스와는 HTTP API로만 통신합니다."
    46	    )
    47	  }
    48	}
    49	
    50	spotless {
    51	  kotlin {
    52	    target("src/**/*.kt")
    53	    ktfmt(version("ktfmt")).googleStyle()
    54	  }
    55	  kotlinGradle {
    56	    target("*.gradle.kts")
    57	    ktfmt(version("ktfmt")).googleStyle()
    58	  }
    59	}
    60	
    61	tasks.withType<Test>().configureEach { useJUnitPlatform() }
    62	
    63	// 이미지에는 실행 산출물 하나만 들어간다: build/libs/<서비스>.jar
    64	tasks.named<Jar>("jar") { enabled = false }
    65	
    66	tasks.named<BootJar>("bootJar") { archiveFileName = "${project.name}.jar" }
    67	
    68	// bootRun은 SPRING_PROFILES_ACTIVE가 없으면 local 프로필로 실행하고, 저장소 secrets/ 의 절대 경로를 넘긴다.
    69	// (configtree는 '..'이 든 상대 경로를 읽지 못하므로 절대 경로로 준다. 컨테이너는 Compose가 /run/secrets 를 넘긴다.)
    70	tasks.named<BootRun>("bootRun") {
    71	  val secrets = rootDir.resolve("secrets")
    72	  systemProperty(
    73	    "spring.profiles.active",
    74	    providers.environmentVariable("SPRING_PROFILES_ACTIVE").getOrElse("local"),
    75	  )
    76	  environment("TASK_SECRETS_DIR", secrets.resolve("${project.name}/config").absolutePath)
    77	  environment("TASK_INTERNAL_SECRETS_DIR", secrets.resolve("internal").absolutePath)
    78	  systemProperty("server.address", "127.0.0.1")
    79	}
